{"version":"Notebook/1.0","items":[{"type":1,"content":{"json":"## Application Portfolio

One view over eight Application Insights resources sharing a single Log Analytics workspace.

Telemetry answers *how is it behaving*. The service catalog answers *what is it, who owns it, and where do I go next* — Azure cannot know that, so it is joined in here. The **Metadata quality** tab shows where the two disagree."},"name":"header"},{"type":9,"content":{"version":"KqlParameterItem/1.0","parameters":[{"id":"p-timerange","version":"KqlParameterItem/1.0","name":"TimeRange","label":"Time range","type":4,"isRequired":true,"typeSettings":{"selectableValues":[{"durationMs":3600000},{"durationMs":14400000},{"durationMs":43200000},{"durationMs":86400000},{"durationMs":172800000}],"allowCustom":true},"timeContext":{"durationMs":86400000},"value":{"durationMs":86400000}},{"id":"p-domain","version":"KqlParameterItem/1.0","name":"Domain","label":"Domain","type":2,"multiSelect":true,"quote":"'","delimiter":",","isRequired":false,"query":"AppCatalog | distinct domain | order by domain asc | project value = domain, label = domain","typeSettings":{"additionalResourceOptions":[],"showDefault":false},"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["__WORKSPACE_ID__"],"value":[]},{"id":"p-tier","version":"KqlParameterItem/1.0","name":"Tier","label":"Criticality","type":2,"multiSelect":true,"quote":"'","delimiter":",","isRequired":false,"query":"AppCatalog | distinct criticality | order by criticality asc | project value = criticality, label = criticality","typeSettings":{"additionalResourceOptions":[],"showDefault":false},"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["__WORKSPACE_ID__"],"value":[]}],"style":"pills","queryType":0},"name":"parameters"},{"type":11,"content":{"version":"LinkItem/1.0","style":"tabs","links":[{"id":"t1","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Portfolio","subTarget":"portfolio","style":"link"},{"id":"t5","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Estate map","subTarget":"map","style":"link"},{"id":"t2","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Domain rollup","subTarget":"domains","style":"link"},{"id":"t3","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Cross-resource","subTarget":"cross","style":"link"},{"id":"t6","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Transactions","subTarget":"txn","style":"link"},{"id":"t4","cellValue":"selectedTab","linkTarget":"parameter","linkLabel":"Metadata quality","subTarget":"meta","style":"link"}]},"name":"tabs"},{"type":3,"content":{"version":"KqlItem/1.0","query":"let selDomain = dynamic([{Domain}]);
let selTier = dynamic([{Tier}]);
let catalog = AppCatalog
    | extend slo = toreal(slo)
    | where (array_length(selDomain) == 0 or domain in (selDomain))
    and (array_length(selTier) == 0 or criticality in (selTier));
let health =
    AppRequests
    | where TimeGenerated {TimeRange}
    | summarize Requests = count(), Failures = countif(Success == false),
                P95ms = round(percentile(DurationMs, 95), 0)
      by workload = AppRoleName;
let services =
    catalog
    | join kind=leftouter health on workload
    | extend Requests = coalesce(Requests, 0), Failures = coalesce(Failures, 0), P95ms = coalesce(P95ms, 0.0)
    | extend Availability = iff(Requests == 0, 0.0, round(100.0 * (Requests - Failures) / Requests, 2))
    | extend Status = case(
        Requests == 0,           "⚪ No data",
        Availability < slo - 1,  "🔴 Breaching SLO",
