| top 100 by TimeGenerated desc","size":0,"title":"Failed requests — click one to trace it","timeContext":{"durationMs":86400000},"queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","crossComponentResources":["__WORKSPACE_ID__"],"gridSettings":{"formatters":[{"columnMatch":"^OperationId$","formatter":5},{"columnMatch":"^Trace$","formatter":7,"formatOptions":{"linkTarget":"RequestDetails","linkLabel":"Details"}},{"columnMatch":"^Resource$","formatter":7,"formatOptions":{"linkTarget":"Resource","linkLabel":"App Insights"}},{"columnMatch":"^Duration ms$","formatter":4,"formatOptions":{"palette":"orange"}}],"rowLimit":100,"filter":true},"exportFieldName":"OperationId","exportParameterName":"selectedOperation","exportDefaultValue":"","noDataMessage":"No failed requests in this time range for the selected filters."},"name":"txn-failures","conditionalVisibility":{"parameterName":"selectedTab","comparison":"isEqualTo","value":"txn"}},{"type":3,"content":{"version":"KqlItem/1.0","query":"let op = "{selectedOperation}";
